#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Lightweight monitor for rt/trained_traj_status.

Usage:
  python subscribe_trained_traj_status.py usb_eth0
  python subscribe_trained_traj_status.py lo
"""

from __future__ import annotations

import signal
import sys
import time

import booster_robotics_sdk_python as br

from common import (
    create_loco_client,
    format_status_snapshot,
    init_channel_factory,
    parse_network_interface,
    parse_robot_name,
    require_highlight_sdk,
    status_to_int,
    usage,
)

_running = True


def _stop(*_args) -> None:
    global _running
    _running = False


def main() -> int:
    if len(sys.argv) > 1 and sys.argv[1] in ("-h", "--help"):
        usage(__file__)
        return 0

    require_highlight_sdk()
    net_if = parse_network_interface(sys.argv)
    robot_name = parse_robot_name(sys.argv)

    signal.signal(signal.SIGINT, _stop)
    signal.signal(signal.SIGTERM, _stop)

    init_channel_factory(net_if)
    client = create_loco_client(robot_name)

    def on_topic(msg: br.TrainedTrajStatusMsg) -> None:
        print(
            "[TOPIC] "
            + format_status_snapshot(msg.status, msg.traj_id)
        )

    sub = br.B1TrainedTrajStatusSubscriber(on_topic, br.kTopicTrainedTrajStatus)
    if robot_name:
        sub.InitChannelWithName(robot_name)
    else:
        sub.InitChannel()
    print(f"Subscribed: {sub.GetChannelName()}")

    last_rpc = None
    while _running:
        resp = client.GetTrainedTrajStatus()
        snap = (
            status_to_int(resp.status),
            resp.traj_id,
        )
        if snap != last_rpc:
            print(
                "[RPC] "
                + format_status_snapshot(resp.status, resp.traj_id)
            )
            last_rpc = snap
        time.sleep(0.5)

    sub.CloseChannel()
    return 0


if __name__ == "__main__":
    sys.exit(main())
